// This file drives the real verify-release.sh against a synthetic release built in a
// temporary directory. Every key here is generated by the test.
package deploy_test

import (
	"crypto/sha256"
	"encoding/hex"
	"fmt"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

const verifier = "./verify-release.sh"

type release struct {
	dir   string
	asset string
	other string
	sums  string
	sig   string
	pub   string
	priv  string
}

func openssl(t *testing.T, args ...string) {
	t.Helper()
	if out, err := exec.Command("openssl", args...).CombinedOutput(); err != nil {
		t.Fatalf("openssl %s: %v\n%s", strings.Join(args, " "), err, out)
	}
}

// keyPair writes an ECDSA P-256 pair into dir under the given base name.
func keyPair(t *testing.T, dir, name string) (priv, pub string) {
	t.Helper()
	priv = filepath.Join(dir, name+".priv")
	pub = filepath.Join(dir, name+".pub")
	openssl(t, "ecparam", "-name", "prime256v1", "-genkey", "-noout", "-out", priv)
	openssl(t, "ec", "-in", priv, "-pubout", "-out", pub)
	return priv, pub
}

func write(t *testing.T, path, content string) {
	t.Helper()
	if err := os.WriteFile(path, []byte(content), 0o644); err != nil {
		t.Fatal(err)
	}
}

func digest(t *testing.T, path string) string {
	t.Helper()
	content, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	sum := sha256.Sum256(content)
	return hex.EncodeToString(sum[:])
}

func (r release) sign(t *testing.T, priv string) {
	t.Helper()
	openssl(t, "dgst", "-sha256", "-sign", priv, "-out", r.sig, r.sums)
}

func (r release) writeManifest(t *testing.T, assets ...string) {
	t.Helper()
	lines := ""
	for _, asset := range assets {
		lines += fmt.Sprintf("%s  %s\n", digest(t, asset), filepath.Base(asset))
	}
	write(t, r.sums, lines)
}

func newRelease(t *testing.T) release {
	t.Helper()
	dir := t.TempDir()
	r := release{
		dir:   dir,
		asset: filepath.Join(dir, "prismotr-1.2.3-linux-amd64"),
		other: filepath.Join(dir, "prismotr-1.2.3-linux-arm64"),
		sums:  filepath.Join(dir, "SHA256SUMS"),
	}
	r.sig = r.sums + ".sig"
	r.priv, r.pub = keyPair(t, dir, "release-signing-key")
	write(t, r.asset, "the amd64 binary\n")
	write(t, r.other, "the arm64 binary\n")
	r.writeManifest(t, r.asset, r.other)
	r.sign(t, r.priv)
	return r
}

func verifierPath(t *testing.T) string {
	t.Helper()
	path, err := filepath.Abs(verifier)
	if err != nil {
		t.Fatal(err)
	}
	return path
}

// verify runs the real script with nothing inherited but PATH.
func verify(t *testing.T, script, pathDir string, args ...string) (stdout, stderr string, err error) {
	t.Helper()
	command := exec.Command("sh", append([]string{script}, args...)...)
	if pathDir == "" {
		pathDir = os.Getenv("PATH")
	}
	command.Env = []string{"PATH=" + pathDir}
	var out, errs strings.Builder
	command.Stdout = &out
	command.Stderr = &errs
	err = command.Run()
	return out.String(), errs.String(), err
}

func (r release) verifyAsset(t *testing.T, args ...string) (stdout, stderr string, err error) {
	t.Helper()
	return verify(t, verifierPath(t), "", append([]string{"--key", r.pub}, args...)...)
}

// spec: release.md#verifying-an-artifact — an asset, manifest and signature as published
// verify, whether or not the manifest is named explicitly.
func TestAnAssetFromTheReleaseVerifies(t *testing.T) {
	r := newRelease(t)
	if stdout, stderr, err := r.verifyAsset(t, r.asset); err != nil {
		t.Fatalf("verifying a published asset failed: %v\n%s%s", err, stdout, stderr)
	}
	if stdout, stderr, err := r.verifyAsset(t, "--sums", r.sums, r.asset); err != nil {
		t.Fatalf("naming the manifest explicitly failed: %v\n%s%s", err, stdout, stderr)
	}
}

// spec: release.md#verifying-an-artifact — with no --key the script reads the key beside
// itself, not beside the artifact.
func TestARunWithNoOptionsUsesTheKeyBesideTheScript(t *testing.T) {
	r := newRelease(t)
	scriptDir := t.TempDir()
	script := filepath.Join(scriptDir, "verify-release.sh")
	write(t, script, read(t, verifier))
	write(t, filepath.Join(scriptDir, "release-signing-key.pub"), read(t, r.pub))
	_, decoy := keyPair(t, t.TempDir(), "decoy")
	write(t, r.pub, read(t, decoy))

	if stdout, stderr, err := verify(t, script, "", r.asset); err != nil {
		t.Fatalf("a run with no options failed: %v\n%s%s", err, stdout, stderr)
	}
}

// spec: release.md#verifying-an-artifact — every way an artifact can fail to be the one the
// release named, and every way the run can be asked the question wrongly.
func TestAVerificationThatMustFail(t *testing.T) {
	tests := []struct {
		name    string
		prepare func(t *testing.T, r *release) []string
		names   string
		usage   bool
	}{
		{"an asset changed by one byte", func(t *testing.T, r *release) []string {
			write(t, r.asset, "the amd64 binary, tampered with\n")
			return []string{r.asset}
		}, "is not the file", false},
		{"an asset renamed to another asset's name", func(t *testing.T, r *release) []string {
			renamed := filepath.Join(r.dir, "prismotr-1.2.3-linux-arm64")
			if err := os.Rename(r.asset, renamed); err != nil {
				t.Fatal(err)
			}
			return []string{renamed}
		}, "is not the file", false},
		{"an artifact the manifest does not list", func(t *testing.T, r *release) []string {
			stranger := filepath.Join(r.dir, "prismotr-9.9.9-linux-amd64")
			write(t, stranger, "a binary from nowhere\n")
			return []string{stranger}
		}, "does not list prismotr-9.9.9-linux-amd64", false},
		{"a manifest changed after signing", func(t *testing.T, r *release) []string {
			write(t, r.asset, "a replacement binary\n")
			r.writeManifest(t, r.asset, r.other)
			return []string{r.asset}
		}, "does not verify", false},
		{"a manifest signed by another key", func(t *testing.T, r *release) []string {
			other, _ := keyPair(t, r.dir, "someone-else")
			r.sign(t, other)
			return []string{r.asset}
		}, "does not verify", false},
		{"no manifest beside the artifact", func(t *testing.T, r *release) []string {
			if err := os.Remove(r.sums); err != nil {
				t.Fatal(err)
			}
			return []string{r.asset}
		}, "no manifest", false},
		{"no signature beside the manifest", func(t *testing.T, r *release) []string {
			if err := os.Remove(r.sig); err != nil {
				t.Fatal(err)
			}
			return []string{r.asset}
		}, "no signature", false},
		{"a signature file that is empty", func(t *testing.T, r *release) []string {
			write(t, r.sig, "")
			return []string{r.asset}
		}, "does not verify", false},
		{"a signature file that is not a signature", func(t *testing.T, r *release) []string {
			write(t, r.sig, "not a signature at all\n")
			return []string{r.asset}
		}, "does not verify", false},
		{"no artifact named", func(_ *testing.T, _ *release) []string { return nil }, "no artifact named", true},
		{"more than one artifact named", func(_ *testing.T, r *release) []string { return []string{r.asset, r.other} }, "one artifact at a time", true},
		{"a directory named", func(_ *testing.T, r *release) []string { return []string{r.dir} }, "is not a file", true},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			r := newRelease(t)
			args := test.prepare(t, &r)

			stdout, stderr, err := r.verifyAsset(t, args...)
			if err == nil {
				t.Fatalf("the run succeeded; it had to fail\n%s%s", stdout, stderr)
			}
			if !strings.Contains(stderr, test.names) {
				t.Errorf("the message does not name %q:\n%s", test.names, stderr)
			}
			if test.usage != strings.Contains(stderr, "usage:") {
				t.Errorf("usage printed = %v, want %v:\n%s", !test.usage, test.usage, stderr)
			}
		})
	}
}

// spec: release.md#verifying-an-artifact — a key that cannot be used is not a bad signature,
// and the run says which of the two it met.
func TestAKeyThatCannotBeUsedIsNamed(t *testing.T) {
	tests := []struct {
		name string
		says string
		key  func(t *testing.T, r release) string
	}{
		{"a path that does not exist", "no public key at", func(_ *testing.T, r release) string {
			return filepath.Join(r.dir, "no-such-key.pub")
		}},
		{"a file that is not a key at all", "is not a public key", func(t *testing.T, r release) string {
			path := filepath.Join(r.dir, "notes.pub")
			write(t, path, "this is prose, not a key\n")
			return path
		}},
	}
	for _, test := range tests {
		t.Run(test.name, func(t *testing.T) {
			r := newRelease(t)
			key := test.key(t, r)

			stdout, stderr, runErr := verify(t, verifierPath(t), "", "--key", key, r.asset)
			if runErr == nil {
				t.Fatalf("the run succeeded; it had to fail\n%s%s", stdout, stderr)
			}
			if !strings.Contains(stderr, key) || !strings.Contains(stderr, test.says) {
				t.Errorf("the message does not name the key %q as %q:\n%s", key, test.says, stderr)
			}
			if strings.Contains(stderr, "does not verify") {
				t.Errorf("an unusable key is reported as a bad signature:\n%s", stderr)
			}
		})
	}
}

// spec: release.md#verifying-an-artifact — a failure names the key and the manifest it used.
func TestAFailureNamesTheKeyAndTheManifestItUsed(t *testing.T) {
	r := newRelease(t)
	write(t, r.asset, "the amd64 binary, tampered with\n")

	stdout, stderr, err := r.verifyAsset(t, r.asset)
	if err == nil {
		t.Fatalf("the run succeeded; it had to fail\n%s%s", stdout, stderr)
	}
	for _, want := range []string{r.pub, r.sums} {
		if !strings.Contains(stderr, want) {
			t.Errorf("the message does not name %q:\n%s", want, stderr)
		}
	}
}

// spec: release.md#verifying-an-artifact — openssl is the one tool the verifier needs.
func TestARunWithoutOpensslNamesIt(t *testing.T) {
	r := newRelease(t)
	stdout, stderr, runErr := verify(t, verifierPath(t), t.TempDir(), "--key", r.pub, r.asset)
	if runErr == nil {
		t.Fatalf("the run succeeded; it had to fail\n%s%s", stdout, stderr)
	}
	if !strings.Contains(stderr, "openssl") {
		t.Errorf("the message does not name openssl:\n%s", stderr)
	}
}

// spec: release.md#the-key — the public half is committed and readable by openssl.
func TestTheShippedKeyIsAPublicKeyOpensslCanRead(t *testing.T) {
	const shippedKey = "release-signing-key.pub"
	if _, err := os.Stat(shippedKey); err != nil {
		t.Fatalf("the repository ships no %s: %v", shippedKey, err)
	}
	if out, err := exec.Command("openssl", "pkey", "-pubin", "-in", shippedKey, "-noout").CombinedOutput(); err != nil {
		t.Errorf("%s is not a public key openssl can read: %v\n%s", shippedKey, err, out)
	}
}

// spec: release.md#verifying-an-artifact — -h is a request, and the PATH holds nothing, which
// pins openssl as the only command outside the shell the script needs.
func TestVerifierHelpPrintsTheUsageOnStdoutAndSucceeds(t *testing.T) {
	stdout, stderr, err := verify(t, verifierPath(t), t.TempDir(), "-h")
	if err != nil {
		t.Fatalf("-h failed: %v\n%s%s", err, stdout, stderr)
	}
	if !strings.Contains(stdout, "usage:") || stderr != "" {
		t.Errorf("the usage is not on stdout alone:\nstdout: %s\nstderr: %s", stdout, stderr)
	}
}
